<script setup lang="ts">
import{ref,onMounted}from'vue';const data=ref<any>({stats:{open:0,resolved:0,occurrences:0},items:[]}),loading=ref(true),error=ref('');const token=()=>sessionStorage.getItem('ops-token')||'';
async function load(){loading.value=true;try{const r=await fetch('/api/admin/knowledge-gaps',{headers:{Authorization:'Bearer '+token()}}),b=await r.json();if(!r.ok)throw Error(b.message);data.value=b.data}catch(e){error.value=e instanceof Error?e.message:'加载失败'}finally{loading.value=false}}
async function resolve(id:number){const r=await fetch('/api/admin/knowledge-gaps/'+id+'/resolve',{method:'PATCH',headers:{Authorization:'Bearer '+token()}});if(r.ok)await load()}onMounted(load);
</script>
<template><section><div class="assistant-head"><div><span class="eyebrow">KNOWLEDGE GAP RADAR</span><h1>知识缺口雷达</h1><p class="muted">从证据不足的真实问题中发现需要补充的知识，而不是凭空猜测主题。</p></div></div><div class="gap-stats"><article><small>待处理缺口</small><strong>{{data.stats.open}}</strong></article><article><small>已解决</small><strong>{{data.stats.resolved}}</strong></article><article><small>累计拒答次数</small><strong>{{data.stats.occurrences}}</strong></article></div><p v-if="error" class="banner error">{{error}}</p><section class="gap-list"><div class="list-caption"><b>缺口清单</b><span>按出现频次排序</span></div><article v-for="g in data.items" :key="g.ID" class="gap-row"><div class="gap-rank">{{g.OCCURRENCE_COUNT}}</div><div><strong>{{g.SAMPLE_QUESTION}}</strong><small>{{g.KNOWLEDGE_BASE}} · 最近出现 {{new Date(g.LAST_SEEN_AT).toLocaleString()}}</small></div><span class="state-tag" :class="{ready:g.STATUS==='RESOLVED'}">{{g.STATUS==='OPEN'?'待补充':'已解决'}}</span><button v-if="g.STATUS==='OPEN'" class="outline" @click="resolve(g.ID)">标记已处理</button></article><div v-if="!loading&&!data.items.length" class="empty"><div class="large-icon">⌁</div><h3>暂未发现知识缺口</h3><p>知识助手因证据不足拒答后，问题会自动汇总到这里。</p></div></section></section></template>
